# Documents déjà enregistrés : numérotés dans l'ordre chronologique, par
# année, puis les compteurs repartent du dernier numéro attribué.
DOCUMENTS = [
    ("TransactionCaisse", "FV", "date_heure"),
    ("Approvisionnement", "BR", "date_reception"),
    ("RetourVente", "AV", "date_heure"),
    ("RetourAppro", "RF", "date_heure"),
    ("Livraison", "BL", "date_creation"),
]


def numeroter_existants(apps, schema_editor):
    Compteur = apps.get_model("superette", "CompteurDocument")
    for nom_modele, prefixe, champ_date in DOCUMENTS:
        modele = apps.get_model("superette", nom_modele)
        compteurs = {}
        for obj in modele.objects.filter(numero__isnull=True).order_by(champ_date, "pk").only("pk", champ_date):
            annee = timezone.localtime(getattr(obj, champ_date)).year
            compteurs[annee] = compteurs.get(annee, 0) + 1
            modele.objects.filter(pk=obj.pk).update(numero=f"{prefixe}-{annee}-{compteurs[annee]:05d}")
        for annee, dernier in compteurs.items():
            Compteur.objects.update_or_create(prefixe=prefixe, annee=annee, defaults={"dernier": dernier})


